    "additions": {
      "occurrences": {
        "reported_accuracy": {
          "file": "paper/main.tex",
          "anchor": {
            "exact": "84.1"
          },
          "metric": "reported_accuracy"
        }
      },
      "metrics": {
        "reported_accuracy": {
          "source": "results/metrics.csv",
          "field": "accuracy",
          "unit": "percent",
          "reduce": "unique",
          "seed_column": "seed",
          "where": {
            "dataset": "Data-A",
            "split": "test"
          }
        }
      },
      "sources": {
        "results/metrics.csv": {
          "path": "results/metrics.csv",
          "format": "csv",
          "columns": {
            "dataset": "string",
            "model": "string",
            "split": "string",
            "seed": "string",
            "accuracy": "decimal"
          },
          "primary_key": [
            "dataset",
            "model",
            "split",
            "seed"
          ]
        }
      }
    },
    "rationale": {
      "reported_accuracy": "The accuracy value of 84.1\\% in the paper/main.tex file is mapped to the corresponding entry in results/metrics.csv for dataset 'Data-A', model 'Ours', split 'test', and seed 2."
    }
  }
}
